    { "id": "en-05-v22", "front": "to grab a coffee / a bite", "back": "prendre un café / manger un morceau (informel)", "example": "Shall we grab a coffee during the break?" },
    { "id": "en-05-v23", "front": "the news (⚠ singulier)", "back": "les actualités, l'actualité (+ verbe au singulier)", "example": "The news is full of the World Cup this week." },
    { "id": "en-05-v24", "front": "a contact", "back": "un contact (professionnel)", "example": "I made three new contacts at the trade fair." }
