        { "phase": "production", "type": "error_hunt", "text": "Yo gusto mucho la música electrónica.", "accepted": ["Me gusta mucho la música electrónica", "A mí me gusta mucho la música electrónica"], "explanation": "Gustar = plaire : me gusta. « Yo gusto » = je plais — le calque n°1 du module." },
        { "phase": "production", "type": "error_hunt", "text": "A mis padres gustan pasear por la playa.", "accepted": ["A mis padres les gusta pasear por la playa"], "explanation": "Deux corrections : le pronom LES manquait, et pasear (infinitif) → singulier gusta, même pour deux personnes." },
        { "phase": "production", "type": "translation", "prompt": "J'adore les séries, mais je déteste les films d'horreur.", "accepted": ["Me encantan las series, pero odio las películas de terror", "Me encantan las series pero odio las películas de terror", "Me encantan las series, pero odio las películas de miedo", "Me encantan las series pero odio las películas de miedo"], "ai_check": true, "explanation": "Encantan (pluriel, structure gustar) d'un côté ; odiar, verbe normal, de l'autre : odio. Les deux systèmes dans une phrase." },
        { "phase": "production", "type": "translation", "prompt": "Mon frère aussi aime jouer au foot.", "accepted": ["A mi hermano también le gusta jugar al fútbol", "A mi hermano le gusta jugar al fútbol también"], "ai_check": true, "explanation": "Tout le module en une phrase : a + personne, LE obligatoire, también, gusta singulier (infinitif), jugar AL fútbol." },
        { "phase": "production", "type": "writing", "prompt": "En 5-6 phrases : ¿Qué te gusta hacer en tu tiempo libre y qué odias? Compara con los gustos de tu socio o de un amigo (a él le gusta…, a mí también / a mí no…).", "constraints": "Force au moins un gusta, un gustan, un « a + personne + le », et un a mí también ou a mí tampoco.", "min_sentences": 5, "ai_correction": true, "target_vocab": [] },
        { "phase": "production", "type": "speaking", "prompt": "Imagina: en una cena en Madrid alguien te pregunta: «¿Cuáles son tus aficiones? ¿Qué te gusta hacer?». Responde durante 90 segundos: habla de tus gustos (música, series, deporte…) y de los gustos de un amigo o de tu socio.", "duration_sec": 90, "mode": "self_record", "checklist": ["Mes accords gusta/gustan sont-ils justes ?", "Ai-je mis le pronom à chaque fois (me…, a él LE…) ?", "Ai-je dit a mí también / a mí tampoco (jamais yo también après me gusta) ?", "Ai-je parlé sans lire ?"] }
