        { "phase": "production", "type": "qcm", "question": "En este barrio ___ tres paradas de metro.", "choices": ["están", "hay", "es"], "answer": 1, "explanation": "Tres paradas = quantité indéfinie → hay, invariable même au pluriel." },
        { "phase": "production", "type": "qcm", "question": "¿Dónde ___ el mercado de San Miguel?", "choices": ["hay", "es", "está"], "answer": 2, "explanation": "Défini (nom propre) + demande de position → está. Ni hay (réservé à l'indéfini), ni ser (la localisation se dit avec estar)." },
        { "phase": "production", "type": "qcm", "question": "Voy a la oficina ___ bici.", "choices": ["en", "a", "con"], "answer": 0, "explanation": "Transport → en : en bici, en metro, en coche. Seul « à pied » échappe à la règle : a pie / andando." },
        { "phase": "production", "type": "qcm", "question": "La farmacia está enfrente ___ hotel.", "choices": ["de el", "del", "al"], "answer": 1, "explanation": "Enfrente de + el = del : contraction obligatoire, jamais « de el » en deux mots." },
        { "phase": "production", "type": "gap_fill", "text": "Perdona, ¿___ un cajero por aquí?", "accepted": ["hay"], "explanation": "Un cajero = indéfini → hay. La question de survie du voyageur." },
        { "phase": "production", "type": "gap_fill", "text": "Nosotros ___ (ir) al centro andando.", "accepted": ["vamos"], "explanation": "Ir : voy, vas, va, vamos, vais, van — et andando = à pied." },
        { "phase": "production", "type": "gap_fill", "text": "El tren ___ (tardar) una hora hasta Valencia.", "accepted": ["tarda"], "explanation": "Tardar = mettre (du temps) — jamais poner. El tren tarda una hora." },
        { "phase": "production", "type": "gap_fill", "text": "Sigue todo ___ hasta la plaza y gira a la derecha.", "accepted": ["recto", "derecho"], "explanation": "Todo recto = tout droit. Formule d'itinéraire à connaître telle quelle, avec hasta (= jusqu'à). En Amérique latine on dit aussi todo derecho — à ne pas confondre avec a la derecha (à droite)." },
        { "phase": "production", "type": "error_hunt", "text": "¿Dónde hay la parada de autobús?", "accepted": ["¿Dónde está la parada de autobús?", "Dónde está la parada de autobús"], "explanation": "La parada = définie (article la) → está. Hay + article défini est impossible — le calque du « où il y a » français." },
        { "phase": "production", "type": "error_hunt", "text": "Este verano voy en Madrid en avión.", "accepted": ["Este verano voy a Madrid en avión"], "explanation": "Destination → a Madrid (mouvement) ; en reste pour le transport (en avión). Le calque in/en de ton test de positionnement — la dernière fois qu'on te le pardonne 😉" },
        { "phase": "production", "type": "translation", "prompt": "Il y a un supermarché à côté de la pharmacie.", "accepted": ["Hay un supermercado al lado de la farmacia", "Al lado de la farmacia hay un supermercado"], "ai_check": true, "explanation": "Un supermercado = indéfini → hay ; al lado DE la farmacia (pas de contraction avec la)." },
        { "phase": "production", "type": "translation", "prompt": "Pour aller à la gare, prends la deuxième rue à gauche.", "accepted": ["Para ir a la estación, coge la segunda calle a la izquierda", "Para ir a la estación, toma la segunda calle a la izquierda"], "ai_check": true, "explanation": "But → PARA ir a (jamais por) ; coger (Espagne) ou tomar (Am. latine) ; la segunda calle a la izquierda — tout le kit itinéraire en une phrase." },
        { "phase": "production", "type": "writing", "prompt": "En 5-6 phrases, décris ton quartier à un ami hispanophone : ce qu'il y a (commerces, transports), où se trouvent deux ou trois endroits importants, et comment tu vas au travail ou en ville.", "constraints": "Au moins 2 hay, 2 está/están, 3 prépositions de lieu et 1 ir en + transport.", "min_sentences": 5, "ai_correction": true, "target_vocab": [] },
        { "phase": "production", "type": "speaking", "prompt": "Dans la rue de ta ville, un touriste espagnol t'arrête : «Perdona, ¿hay una farmacia por aquí? ¿Y cómo llego a la estación?». Réponds en espagnol pendant 90 secondes : dis où est la pharmacie (prépositions de lieu), puis donne-lui l'itinéraire vers la gare (todo recto, a la derecha, cruza…) et le transport possible.", "duration_sec": 90, "mode": "self_record", "checklist": ["Mes hay / está sont-ils bien répartis (indéfini → hay, défini → está) ?", "Mes prépositions gardent-elles leur de (al lado DE, enfrente DE, delante DE) ?", "Ai-je dit al / del pour a + el / de + el ?", "Ai-je parlé sans lire ?"] }
